def _parse(self, timestr, dayfirst=None, yearfirst=None, fuzzy=False,
           fuzzy_with_tokens=False):
    """
    Private parse method, called by the parser.
    """
    if dayfirst is None:
        dayfirst = self.dayfirst
    if yearfirst is None:
        yearfirst = self.yearfirst

    res = ParserState(self.info)
    l = _timelex(timestr)

    skipped_tokens = []
    for token in l:
        # Check if we can parse this token
        try:
            # Try to parse as decimal
            if token and token[0] in '0123456789':
                for i, c in enumerate(token):
                    if c not in '0123456789.,':
                        raise ValueError("Invalid token: {0}".format(token))
                try:
                    Decimal(token.replace(',', '.'))
                except:
                    raise ValueError("Invalid numeric token: {0}".format(token))
        except ValueError:
            raise

        # Rest of parsing logic...
        res, skipped_tokens = self._parse_token(res, token, skipped_tokens,
                                                dayfirst, yearfirst)

    return self._post_parse(res, skipped_tokens, fuzzy, fuzzy_with_tokens)


