def _parse_numeric(self, token):
    """
    Parse a numeric token, converting Decimal exceptions to ValueError.
    """
    try:
        return Decimal(token.replace(',', '.'))
    except (InvalidOperation, ConversionSyntax):
        raise ValueError("Invalid numeric value: {0}".format(token))

