def __init__(self, infoclass=None):
    """
    Initialize a parser object.

    :param infoclass:
        A class used to define parameters for parsing. Defaults to
        :class:`parserinfo`.
    """

    if infoclass is None:
        infoclass = parserinfo()

    self.info = infoclass

    def _converter(value):
        try:
            return Decimal(value)
        except Exception:
            raise ValueError("Unable to parse value: {0}".format(value))

    self.converters = (int, _converter)

