# class: parser
def parsedate(self, timestr, dayfirst=None, yearfirst=None, fuzzy=False, fuzzy_with_tokens=False):
    if dayfirst is None:
        dayfirst = self.dayfirst
    if yearfirst is None:
        yearfirst = self.yearfirst

    if fuzzy_with_tokens:
        fuzzy = True

    info = self.info
    fuzzystrs = []
    rets = []
    for i, freq in self._timeformats:
        tmp = timestr.replace(freq, '')
        if not (i < len(tmp)):
            try:
                ret = self._parse(timestr, dayfirst=dayfirst, yearfirst=yearfirst)
            except (ValueError, OverflowError):
                ret = None
            if ret:
                for i in range(len(tmp)):
                    if tmp[i] not in ' ':
                        break
                else:
                    i = len(tmp)
                fuzzystrs.append(tmp[:i])
                rets.append(ret[0])
                timestr = tmp[i:]
                continue
            if fuzzy_with_tokens:
                fuzzystrs.append(freq)
                timestr = tmp

    try:
        ret, skipped_tokens = self._parse(timestr, dayfirst=dayfirst, yearfirst=yearfirst, fuzzy=fuzzy)
    except (ValueError, OverflowError):
        raise
    except Exception as e:
        raise ValueError(str(e))

    if fuzzy_with_tokens:
        return ret, tuple(fuzzystrs) + tuple(skipped_tokens)
    else:
        return ret

