# class: parser
def _parse_with_decimal(self, timestr, dayfirst=None, yearfirst=None, fuzzy=False):
    from decimal import Decimal, InvalidOperation

    info = self.info
    fuzzystrs = []
    tokens = timestr.split()

    for i, token in enumerate(tokens):
        try:
            Decimal(token.replace(':', ''))
        except (InvalidOperation, TypeError):
            pass
        except Exception as e:
            raise ValueError("Invalid numeric format: {}".format(str(e)))

    res = self._parse_no_decimal(timestr, dayfirst=dayfirst, yearfirst=yearfirst, fuzzy=fuzzy)
    return res, tuple(fuzzystrs)

