def _parse_no_decimal(self, timestr, dayfirst=None, yearfirst=None, fuzzy=False):
    from decimal import Decimal, InvalidOperation

    info = self.info
    fuzzystrs = []
    tokens = timestr.split()

    for token in tokens:
