def dump(self, obj, many=None, update_fields=True, **kwargs):
    """Serialize an object to native Python data types.

    Args:
        obj: The object to serialize.
        many (bool): Whether to serialize `obj` as a collection. If `None`, the
            value of `self.many` is used.
        update_fields (bool): Whether to update the schema's field objects.
            Defaults to `True`.
        **kwargs: Additional keyword arguments passed to `_do_dump`.

    Returns:
        A dictionary of the serialized data.
    """
    many = self.many if many is None else many
    if update_fields is True:
        self._init_fields()
    if many:
        result = [
            self._do_dump(obj=item, many=False, parent=self, **kwargs)
            for item in obj
        ]
    else:
        result = self._do_dump(obj=obj, many=False, parent=self, **kwargs)
    return result

