# class: Schema
def _do_dump(self, obj, many, parent=None, **kwargs):
    """Inner dump logic."""
    field_errors = {}
    error_list = []
    result = {}

    for attr_name, field_obj in self.fields.items():
        try:
            result[attr_name] = field_obj._serialize(
                getattr(obj, attr_name, missing_), attr_name, obj, **kwargs
            )
        except ValidationError as error:
            field_errors[attr_name] = error.messages
        except AttributeError as error:
            if field_obj.dump_default is missing_:
                field_errors[attr_name] = error
            else:
                result[attr_name] = field_obj.dump_default
        except Exception as error:
            field_errors[attr_name] = error

    if error_list:
        raise ValidationError(error_list, data=obj, valid_data=result)
    if field_errors:
        raise ValidationError(field_errors, data=obj, valid_data=result)

    return result

