def _invoke_dump_processors(self, pass_many, data, many, original_data=None, **kwargs):
    """Run dump processors."""
    if pass_many:
        tag_processor = lambda fn: hasattr(fn, '__marshmallow_hook__') and fn.__marshmallow_hook__.get('pass_many')
    else:
        tag_processor = lambda fn: hasattr(fn, '__marshmallow_hook__') and not fn.__marshmallow_hook__.get('pass_many')

    for fn in filter(tag_processor, self.__processors__):
        try:
            data = fn(data, many=many, original_data=original_data, **kwargs)
        except ValidationError as error:
            raise error
    return data

