def _do_serialize(self, obj, many=False, update_fields=True, partial=False):
    """Serialize `obj` based on the declared fields.

    Args:
        obj: The object to serialize.
        many: Whether to serialize as a collection.
        update_fields: Whether to update field instances.
        partial: Whether to allow partial serialization.

    Returns:
        A tuple of (serialized_data, errors).
    """
    if many:
        many_schema = self.many_schema_class(
            self, many=False, context=self.context, load_only=self.load_only,
            dump_only=self.dump_only
        )
        ret = [
            many_schema._do_serialize(
                d, many=False, update_fields=False, partial=partial
            )
            for d in obj
        ]
        serialized = [r[0] if isinstance(r, tuple) else r for r in ret]
        errors = {}
        for idx, r in enumerate(ret):
            if isinstance(r, tuple) and r[1]:
                errors[idx] = r[1]
        return serialized, errors

    errors = {}
    result = {}

    for attr_name, field_obj in self.fields.items():
        if field_obj.dump_only is False:
            continue
        try:
            attribute = field_obj.get_value(obj)
        except AttributeError as error:
            pass
        else:
            try:
                serialized = field_obj._serialize(attribute, attr_name, obj)
            except ValidationError as error:
                errors.update(error.messages if isinstance(error.messages, dict) else {attr_name: error.messages})
            except type(error) as error:
                raise
            else:
                if serialized is not missing:
                    result[attr_name] = serialized

    return result, errors

