def _do_dump(self, obj, *, many=False, update_fields=True, postprocess=True):
    """Performs the actual dumping of the object(s)."""
    if many:
        if not isinstance(obj, (list, tuple)):
            self.fail("invalid")
        result = [
            self._do_dump(d, many=False, update_fields=False, postprocess=postprocess)
            for d in obj
        ]
        return result

    result = {}
    errors = {}

    if update_fields:
        self._init_fields()

    for attr_name, field_obj in self.fields.items():
        try:
            value = field_obj.serialize(attr_name, obj, accessor=self.get_attribute)
        except ValidationError as error:
            errors[attr_name] = error.messages
            continue
        except AttributeError as error:
            if self.many:
                errors[attr_name] = [str(error)]
            else:
                errors[attr_name] = str(error)
            continue
        except TypeError as error:
            if field_obj.allow_none:
                value = None
            else:
                raise

        if value is missing_:
            continue

        result[attr_name] = value

    if errors:
        raise ValidationError(errors)

    if postprocess:
        result = self._invoke_load_processors(
            POST_DUMP, result, many=many, original_data=obj
        )

    return result

