                else:
                    existing_errors[field_name]['_schema'].extend(
                        [new_errors] if not isinstance(new_errors, list) else new_errors
                    )
        else:
            existing_errors[field_name] = {'_schema': [new_errors]}
    else:
        if isinstance(existing_errors[field_name], dict):
