# class: Schema
def _run_validators(self, *, data, many, partial, original_data=None):
    errors = {}
    for attr_name in self._hooks[(VALIDATES_SCHEMA, False)]:
        attr = getattr(self, attr_name)
        try:
            attr(data, many=many, partial=partial, original_data=original_data)
        except ValidationError as error:
            errors = self._merge_schema_errors(errors, error, many=many)
    return errors

# class: Schema
def _merge_schema_errors(self, errors, error, *, many):
    from marshmallow.fields import Field

    new_errors = error.messages if isinstance(error.messages, dict) else {}

    if isinstance(error.messages, str):
        # string 형태 에러인 경우 field_name 사용
        field_name = error.field_name
        if field_name:
            # data_key 매핑
            field_obj = self.fields.get(field_name)
            if field_obj and hasattr(field_obj, 'data_key') and field_obj.data_key:
                field_name = field_obj.data_key
            errors.setdefault(field_name, []).extend(
                error.messages if isinstance(error.messages, list) else [error.messages]
            )
    elif isinstance(error.messages, dict):
        # dict 형태 에러인 경우, 키를 field_name -> data_key로 매핑
        for key, msgs in error.messages.items():
            mapped_key = key
            # 역으로 data_key에서 field_name을 찾아 field_obj를 조회
            for field_name, field_obj in self.fields.items():
                if hasattr(field_obj, 'data_key') and field_obj.data_key == key:
                    mapped_key = key
                    break
                elif field_name == key:
                    if hasattr(field_obj, 'data_key') and field_obj.data_key:
                        mapped_key = field_obj.data_key
                    break
            errors.setdefault(mapped_key, []).extend(
                msgs if isinstance(msgs, list) else [msgs]
            )

    return errors

