# class: ErrorStore
    def store_error(self, messages, field_name=SCHEMA, index=None):
        # field error  -> store/merge error messages under field name key
        # schema error -> if string or list, store/merge under _schema key
        #              -> if dict, store/merge with other top-level keys
        if field_name != SCHEMA or not isinstance(messages, dict):
            messages = {field_name: messages}
        if index is not None:
            messages = {index: messages}
        self.errors = merge_errors(self.errors, messages)

    def normalize_errors(self, field_names_to_data_keys):
        """Normalize field names to data_keys in stored errors."""
        if not field_names_to_data_keys:
            return

        normalized_errors = {}
        for key, value in self.errors.items():
            # Check if this key is a field name that needs to be converted to data_key
            if key in field_names_to_data_keys:
                new_key = field_names_to_data_keys[key]
            else:
                new_key = key
            normalized_errors[new_key] = value

        self.errors = normalized_errors

