class ErrorStore:
    def __init__(self):
        self.errors: dict[str, typing.Any] = {}

    def store_error(
        self,
        messages: str | list[str] | dict[str, typing.Any],
        field_name: str | None = None,
        *,
        index: int | None = None,
    ) -> None:
        if isinstance(messages, dict):
            for key, value in messages.items():
                self._add_error(key, value, index)
        else:
            if field_name is None:
                field_name = "_schema"
            self._add_error(field_name, messages, index)

    def _add_error(
        self,
        field_name: str,
        messages: str | list[str],
        index: int | None = None,
    ) -> None:
        if isinstance(messages, str):
            messages = [messages]

        if index is not None:
            self.errors.setdefault(field_name, {})
            if not isinstance(self.errors[field_name], dict):
                self.errors[field_name] = {}
            self.errors[field_name].setdefault(index, [])
            self.errors[field_name][index].extend(messages)
        else:
            self.errors.setdefault(field_name, [])
            if isinstance(self.errors[field_name], dict):
                self.errors[field_name] = []
            self.errors[field_name].extend(messages)

