def _normalize_error_messages(error, field_map):
    """ValidationError 메시지의 필드명을 data_key로 정규화합니다."""
    if isinstance(error.messages, dict):
        normalized = {}
        for key, value in error.messages.items():
            # field_name을 data_key로 매핑
            mapped_key = field_map.get(key, key)
            normalized[mapped_key] = value
        error.messages = normalized
    elif error.field_name != SCHEMA and error.field_name in field_map:
        error.field_name = field_map[error.field_name]
    return error

