def _run_schema_validators(schema, validators, data, many, field_data=None):
    """스키마 유효성 검사자를 실행하고 data_key를 고려하여 에러를 정규화합니다."""
    field_map = {}
    for field_name, field_obj in schema.fields.items():
        data_key = field_obj.data_key or field_name
        if data_key != field_name:
            field_map[field_name] = data_key

    errors = {}
    for validator in validators:
        try:
            validator(schema, data)
        except ValidationError as error:
            # field_name을 data_key로 변환
            if error.field_name != SCHEMA and error.field_name in field_map:
                error.field_name = field_map[error.field_name]
            # dict 형식의 메시지도 정규화
            if isinstance(error.messages, dict):
                normalized = {}
                for key, value in error.messages.items():
                    mapped_key = field_map.get(key, key)
                    if mapped_key in errors:
                        if isinstance(errors[mapped_key], list):
                            errors[mapped_key].extend(value if isinstance(value, list) else [value])
                        else:
                            errors[mapped_key] = [errors[mapped_key], value]
                    else:
                        errors[mapped_key] = value
            else:
                field = error.field_name
                if field in errors:
                    if isinstance(errors[field], list):
                        errors[field].extend(error.messages if isinstance(error.messages, list) else [error.messages])
                    else:
                        errors[field] = [errors[field]] + (error.messages if isinstance(error.messages, list) else [error.messages])
                else:
                    errors[field] = error.messages
    return errors

