def store_error(
    self,
    messages: typing.Any,
    field_name: str | None = None,
    *,
    index: int | None = None,
) -> None:
    """Store an error with optional field_name and index.

    If field_name is a dict and messages is a dict with field names as keys,
    merge them properly. Otherwise store as usual.
    """
    if field_name is None:
        field_name = "error"

    if isinstance(messages, dict) and not isinstance(field_name, str):
        for key, msg in messages.items():
            self.store_error(msg, field_name=key, index=index)
    elif isinstance(messages, dict):
        # messages is a dict, treat it as field_name -> message mapping
        for key, msg in messages.items():
            self.store_error(msg, field_name=key, index=index)
    else:
        if isinstance(messages, str):
            messages = [messages]

        # Normalize messages to list
        if not isinstance(messages, list):
            messages = [messages]

        if index is not None:
            if field_name not in self._errors:
                self._errors[field_name] = []
            self._errors[field_name].append({index: messages})
        else:
            if field_name not in self._errors:
                self._errors[field_name] = []
            self._errors[field_name].extend(messages)

