def set_hook(
    fn: Callable[..., Any] | None = None,
    tag: str = "",
    **kwargs: Any,
) -> Callable[..., Any]:
    """Register a hook on the schema.

    :param fn: The decorated function.
    :param tag: The hook tag.
    """
    def decorator(fn: Callable[..., Any]) -> Callable[..., Any]:
        @wraps(fn)
        def wrapper(self: Schema, *args: Any, **kwargs_inner: Any) -> Any:
            try:
                return fn(self, *args, **kwargs_inner)
            except ValidationError as ve:
                # Normalize field names in the error using data_key mapping
                if self.fields:
                    field_name_to_data_key = {
                        field_name: field.data_key or field_name
                        for field_name, field in self.fields.items()
                        if field.data_key
                    }

                    if ve.messages:
                        if isinstance(ve.messages, dict):
                            # Map field names to data_keys in messages dict
                            normalized_messages = {}
                            for key, value in ve.messages.items():
                                # Check if this key is a field name that has a data_key
                                if key in field_name_to_data_key:
                                    data_key = field_name_to_data_key[key]
                                    normalized_messages[data_key] = value
                                else:
                                    normalized_messages[key] = value
                            ve.messages = normalized_messages

                        if ve.field_name and ve.field_name in field_name_to_data_key:
                            ve.field_name = field_name_to_data_key[ve.field_name]

                raise

        wrapper.__marshmallow_hook__ = {tag, **kwargs}
        return wrapper

    if fn is None:
        return decorator
    return decorator(fn)

