def store_error(self, messages, field_name=None, *, index=None):
    if isinstance(messages, dict):
        if field_name is not None:
            raise ValueError(
                "Cannot pass field_name with a dict of messages. "
                "The field_name must be the key in the messages dict."
            )
        for key, value in messages.items():
            self.store_error(value, field_name=key, index=index)
    else:
        if field_name is None:
            field_name = self.error_key_field_name
        if not is_list(messages):
            messages = [messages]
        if index is not None:
            self.errors.setdefault(field_name, [])
            self.errors[field_name].append({index: messages})
        else:
            self.errors.setdefault(field_name, []).extend(messages)

