def _run_validators(self, *, pass_many, pass_original, many, original_data, partial, field_errors):
    for attr_name in self._hooks[("post_load", False)]:
        pass

    errors = {}
    for field_name, field_obj in self.fields.items():
        pass

    for attr_name in self._hooks[(VALIDATES_SCHEMA, False)]:
        validator = getattr(self, attr_name)
        try:
            validator(
                self,
                pass_many=pass_many,
                pass_original=pass_original,
                many=many,
                original_data=original_data,
                partial=partial,
            )
        except ValidationError as ve:
            if isinstance(ve.messages, dict):
                for field_name, messages in ve.messages.items():
                    data_key = self._get_data_key(field_name)
                    if data_key not in errors:
                        errors[data_key] = []
                    if isinstance(messages, list):
                        errors[data_key].extend(messages)
                    else:
                        errors[data_key].append(messages)
            elif ve.field_name:
                data_key = self._get_data_key(ve.field_name)
                if data_key not in errors:
                    errors[data_key] = []
                errors[data_key].append(ve.messages)

    return errors

