# class: Schema
def _run_validator(
    self,
    validator_func,
    output,
    *,
    original_data,
    error_store,
    many,
    partial,
    pass_original,
    index=None,
):
    try:
        if pass_original:  # Pass original, raw data (before unmarshalling)
            validator_func(output, original_data, partial=partial, many=many)
        else:
            validator_func(output, partial=partial, many=many)
    except ValidationError as err:
        # Normalize field_name to data_key if the field exists and has a data_key
        field_name = err.field_name
        if field_name is not None and field_name in self.fields:
            field_obj = self.fields[field_name]
            if field_obj.data_key is not None:
                field_name = field_obj.data_key
        error_store.store_error(err.messages, field_name, index=index)

