class Validator(BaseSerializer):
    """Validator class for deserializing and validating data."""

    def __init__(self, strict=False):
        super(Validator, self).__init__()
        self.strict = strict
        self._declared_fields = OrderedDict([
            ('email', fields.Email(required=True)),
            ('colors', fields.String(validate=lambda x: x in ['red', 'blue', 'green'])),
            ('age', fields.Integer(validate=lambda x: x >= 0)),
        ])
        self.fields = self._declared_fields

    def target_function(self, data):
        """Deserialize and validate data, returning (result, errors) tuple."""
        errors = {}
        result = {}

        for field_name, field_obj in self.fields.items():
            if field_name in data:
                try:
                    result[field_name] = field_obj.deserialize(data[field_name])
                except Exception as e:
                    errors[field_name] = [str(e)]
            elif field_obj.required:
                errors[field_name] = ['Field is required.']

        if self.strict and errors:
            raise ValueError(errors)

        return result, errors

