def decode(self, s):
    """
    Decode a JSON string with registered serializers.

    :param s: Encoded JSON string with type information
    :return: Decoded JSON string with original objects
    """
    import json

    def _decode_obj(obj):
        if isinstance(obj, dict):
            if obj.get('__serialized__') is True:
                type_name = obj.get('__type__')
                data = obj.get('__data__')
                for serializer in self._serializers:
                    if hasattr(serializer, '__class__') and serializer.__class__.__name__.replace('Serializer', '') == type_name or type_name in [k for k, v in self._type_map.items() if v == serializer.__class__.__name__]:
