                # Find serializer by registered type name
                for reg_type, serializer in self._serializer_map.items():
                    if reg_type == type_name:
                        return serializer.decode(data)
                return obj
            else:
                return {k: _decode_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_decode_obj(item) for item in obj]
        return obj

    data = json.loads(s)
    decoded_data = _decode_obj(data)
    return json.dumps(decoded_data)

