def _deserialize(self, obj):
    """
    Recursively deserialize an object using registered serializers.

    :param obj: object to deserialize
    :return: deserialized object
    """
    if isinstance(obj, dict):
        if obj.get('__serialized__') is True:
            serializer_name = obj.get('__type__')
            value = obj.get('__value__')
            serializer = self.serializer_dict.get(serializer_name)
            if serializer:
                return serializer.decode(value)
            return obj
        return {k: self._deserialize(v) for k, v in obj.items()}
    elif isinstance(obj, (list, tuple)):
        return [self._deserialize(item) for item in obj]
    else:
        return obj

