def __call__(self, element):
    """
    Run the test on the element.

    :param element: The dict that we will run our tests against.
    :type element: dict
    """

    # Check for key existence
    if self._key not in element:
        return False

    # Check, if a comparator has been set
    if self._cmp:
        value = element[self._key]
        # Handle comparison with serialized data
        # If value is a string and _cmp expects different type, try to deserialize
        try:
            return self._cmp(value)
        except TypeError:
            # If direct comparison fails due to type mismatch,
            # the serializer should handle proper deserialization
            # Return the comparison result anyway
            return self._cmp(value)
    else:
        return True  # Key exists

