def decode(self, s):
    """
    Decode an object.

    :param s:
    :type s: str
    :return:
    """
    if isinstance(s, dict) and '__type__' in s:
        serializer_name = s['__type__']
        if serializer_name in self._serializers:
            return self._serializers[serializer_name].decode(s['value'])
    return s

