# class: SerializationMiddleware
def read(self):
    """
    Read and deserialize data from the underlying storage.
    """
    data = self._storage.read()
    return self._deserialize(data)

def _deserialize(self, obj):
    """
    Recursively deserialize objects using registered serializers.
    """
    if isinstance(obj, dict):
        if '__class__' in obj:
            class_name = obj['__class__']
            if class_name in self._serializers:
                return self._serializers[class_name].obj_hook(obj)
        return {k: self._deserialize(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [self._deserialize(item) for item in obj]
    return obj

