@contextmanager
def catch_warning(warning_cls):
    warning_filter = [f for f in warnings.filters if f[2] == warning_cls]
    warnings.filterwarnings(action="error", category=warning_cls)

    try:
        yield  # Run user code
    finally:
        # Always reset the filter, even if an exception occurs
        warnings.filters[:] = [f for f in warnings.filters if f[2] != warning_cls]
        if warning_filter:
            # Reset original filter - insert at the beginning to maintain order
            warnings.filters.insert(0, warning_filter[0])

